<?php
// maak een verbinding met de database
$pdo = new PDO("mysql:host=localhost;dbname=portfolio", $username, $password);


// haal de projecten op uit de database
$stmt = $pdo->query("SELECT * FROM projecten");

// sla de projecten op in een array
$projecten = $stmt->fetchAll(PDO::FETCH_ASSOC);

// maak een functie om de gemaakte grojecten weer te geven
function toonProjecten($projecten)

// genereer de HTML voor elk project
{
    foreach ($projecten as $project) {
        echo '<div class="col-md-4">';
        echo '<div class="bg-dark p-4 rounded" style="height: 150px;">';
        echo '<h5><a href="' . htmlspecialchars($project['link']) . '" class="text-white">' . htmlspecialchars($project['titel']) . '</a></h5>';
        echo '</div>';
        echo '</div>';
    }
}


